    if (linear_init(&model->dec_gru3_input, arrays, "dec_gru3_input_bias", "dec_gru3_input_subias", "dec_gru3_input_weights_int8","dec_gru3_input_weights_float", "dec_gru3_input_weights_idx", NULL, "dec_gru3_input_scale", 352, 288)) return 1;
    if (linear_init(&model->dec_gru3_recurrent, arrays, "dec_gru3_recurrent_bias", "dec_gru3_recurrent_subias", "dec_gru3_recurrent_weights_int8","dec_gru3_recurrent_weights_float", NULL, NULL, "dec_gru3_recurrent_scale", 96, 288)) return 1;
    if (linear_init(&model->dec_gru4_input, arrays, "dec_gru4_input_bias", "dec_gru4_input_subias", "dec_gru4_input_weights_int8","dec_gru4_input_weights_float", "dec_gru4_input_weights_idx", NULL, "dec_gru4_input_scale", 480, 288)) return 1;
